#!/usr/bin/env bash
# test-cf-old-login-token-remint-bootstrap.sh — the #12931 Phase 5 token-slice bootstrap (bootstrap.sh in the
# feat-one-shot-12931-phase5-token-remint spec directory, generated by soleur:operator-bootstrap), plan
# 2026-11-27-chore-cf-phase5-old-login-token-remint-plan.md "## Guard Contract" and "## Test Scenarios".
#
#   bash tests/scripts/test-cf-old-login-token-remint-bootstrap.sh            every row, then every mutant
#   bash tests/scripts/test-cf-old-login-token-remint-bootstrap.sh --mutants  the mutation section only
#
# Properties: the plan's "## Guard Contract" (rows G1-*, G2-*, G3-*) and "## Test Scenarios" (rows S*); each
# row asserts the refusal TEXT or marker, never only an exit code.
#
# ASSEMBLY. A fixture git repository per world holds a copy of bootstrap.sh at its real relative path plus
# committed stubs of cloudflare-readonly.sh and check-cloudflare-token-drift.sh (the bootstrap runs only
# TRACKED files). PATH-stubbed `doppler` keeps state in $STUB_D/<project>/<config>/<NAME> files: `get
# --plain` prints the value plus ONE newline (the real CLI), `set` stores stdin exactly and logs
# `set <p>/<c>/<NAME> prev=<class of <NAME>_PREV at that moment>` (Guard 2's in-window order witness),
# `projects` / `configs` / `--only-names` list the state, `run` execs with the config's values exported.
# PATH-stubbed `curl` answers both verify endpoints and GraphQL from the token's sentinel KIND; `gh` is
# stubbed and must never be called. Nothing reaches a network. Values are synthesized sentinels
# (cq-test-fixtures-synthesized-only); the ids are the public account/zone ids of the runbook id table.
#
# MUTATIONS (--mutants, and the tail of a full run): each `mkill` label names its mutant, row, step and the
# reason the row must observe (killed() rejects a red anywhere else, or for another reason). HARNESS rows (`hred`)
# run a row on the REAL script under a deliberately broken stub and must go red the same way.
#
# LOCATION: this suite lives in tests/scripts and finds bootstrap.sh by glob, so an archive-kb move of the
# spec directory breaks nothing; exactly one match is required, else exit 2.
set -uo pipefail

export TMPDIR="${TMPDIR:-/var/tmp}"
export LC_ALL=C

MODE=full
case "${1:-}" in
  "") ;;
  --mutants) MODE=mutants ;;
  *) printf 'usage: %s [--mutants]\n' "$0" >&2; exit 2 ;;
esac

SUITE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(git -C "$SUITE_DIR" rev-parse --show-toplevel 2>/dev/null)" || { printf 'HARNESS: not in a git work tree\n' >&2; exit 2; }
_found=()   # a read loop, not mapfile: the suite stays runnable on bash 3.2
while IFS= read -r _f; do _found[${#_found[@]}]="$_f"; done < <(git -C "$REPO_ROOT" ls-files --cached --others --exclude-standard --full-name \
  '*feat-one-shot-12931-phase5-token-remint/bootstrap.sh')
[[ "${#_found[@]}" -eq 1 ]] || { printf 'HARNESS: expected exactly one phase5 token-remint bootstrap.sh, found %s\n' "${#_found[@]}" >&2; exit 2; }
SCRIPT_SRC="${REPO_ROOT}/${_found[0]}"
REL="${_found[0]}"  # the glob result, so this suite survives archive-kb moving the directory
LIB="${REPO_ROOT}/plugins/soleur/scripts/lib/operator-script.sh"
HOOK="${REPO_ROOT}/plugins/soleur/hooks/operator-stage-approval.sh"

assert_fixture_dir() {
  case "${1-}" in
    "") printf 'FATAL: fixture dir is EMPTY; git -C "" would operate on %s\n' "$PWD" >&2; exit 2 ;;
    */../*|*/..) printf 'FATAL: fixture dir %s contains ..; refusing\n' "$1" >&2; exit 2 ;;
    /proc/*|/sys/*|/dev/*) printf 'FATAL: fixture dir %s is a synthetic-fs path; refusing\n' "$1" >&2; exit 2 ;;
    /|//|/.) printf 'FATAL: fixture dir resolves to the filesystem root; refusing\n' >&2; exit 2 ;;
    /*) : ;;
    *)  printf 'FATAL: fixture dir %s is RELATIVE; refusing\n' "$1" >&2; exit 2 ;;
  esac
}

# shellcheck source=../../plugins/soleur/test/lib/git-fixture-env.sh
source "${REPO_ROOT}/plugins/soleur/test/lib/git-fixture-env.sh"

for bin in jq timeout git perl cmp sha256sum; do command -v "$bin" >/dev/null 2>&1 || { printf 'HARNESS: %s is required\n' "$bin" >&2; exit 2; }; done
[[ -r "$SCRIPT_SRC" && -r "$LIB" && -r "$HOOK" ]] || { printf 'HARNESS: script, library or hook missing\n' >&2; exit 2; }

PASS=0; FAIL=0
pass() { PASS=$((PASS + 1)); echo "  [ok] $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  [FAIL] $1" >&2; }
check() { if [[ "$2" -eq 0 ]]; then pass "$1"; else fail "$1 (last out: $(printf '%s' "${OUT:-}" | tr '\n' ' ' | cut -c1-400))"; fi; }

# Instrument self-test (ADR-193 shape): both helpers must move their counter, or nothing below means anything.
check "instrument self-test (pass arm)" 0 >/dev/null
check "instrument self-test (fail arm)" 1 >/dev/null 2>&1
if [[ "$PASS" -ne 1 || "$FAIL" -ne 1 ]]; then printf 'INSTRUMENT SELF-TEST FAILED (pass=%s fail=%s)\n' "$PASS" "$FAIL" >&2; exit 2; fi
FAIL=0   # PASS keeps the self-test's one pass; the floor at the bottom subtracts it (SELFTEST_PASSES)

SB="$(mktemp -d "${TMPDIR}/cf-p5-remint.XXXXXXXX")" || { printf 'HARNESS: mktemp failed\n' >&2; exit 2; }
trap 'chmod -R u+rwx "$SB" 2>/dev/null; rm -rf "$SB"' EXIT
ALL_OUT="$SB/all-output.log"; : > "$ALL_OUT"

readonly NZ=951ce525552201ec6c696b24251abed7 NA=66d4f93f7397f196544e9fe84c3557c2
readonly OZ=5af02a2f394e9ba6e0ea23c381a26b67
readonly TFC=prd_terraform
# The keys and their pinned old-id prefixes come from the script's own `# P5-MANIFEST` lines (a rotation edits only
# that block, CTO F18); the stubs read them from STUB_PINS. KA / KN / KP name the three consumers this suite models.
KEYS=(); STUB_PINS=""
while IFS='|' read -r _k _p _h; do
  _k="${_k#\# P5-MANIFEST }"; _k="${_k//[[:space:]]/}"; _p="${_p//[[:space:]]/}"
  KEYS[${#KEYS[@]}]="$_k"; STUB_PINS="${STUB_PINS:+$STUB_PINS }${_k}=${_p}"
done < <(grep -a '^# P5-MANIFEST ' "$SCRIPT_SRC")
readonly KEYS STUB_PINS
pin_of() { local e; for e in $STUB_PINS; do [[ "${e%%=*}" != "$1" ]] || { printf '%s\n' "${e#*=}"; return 0; }; done; return 1; }
readonly KA=CF_API_TOKEN_AUDIT KN=CF_API_TOKEN_ANALYTICS_READ KP=CF_API_TOKEN_PAGERULES_READ
for _k in "$KA" "$KN" "$KP"; do pin_of "$_k" >/dev/null || { printf 'HARNESS: the manifest has no %s line\n' "$_k" >&2; exit 2; }; done
tok() { printf 'SYNTH-%s-%s-SENTINEL' "$1" "$2"; }   # tok <KIND> <KEY>

# --- stubs ----------------------------------------------------------------------
write_stubs() { # <bin-dir>
  local b="$1"; assert_fixture_dir "$b"; mkdir -p "$b"
  cat > "$b/doppler" <<'DOPPLER'
#!/usr/bin/env bash
# State: $STUB_D/<project>/<config>/<NAME> holds a value byte-exact. Flags in $STUB_D/.flags:
#   projects-empty | projects-fail          `doppler projects` answers [] / fails
#   unreadable.<p>.<c>                      the names listing of <p>/<c> fails
#   get-fails.<p>.<c>.<NAME>                a get of that (listed) name fails
#   corrupt.<p>.<c>.<NAME>                  a set of that name stores a DIFFERENT value
#   get-empty                               HARNESS H1: every get answers an empty value
#   get-as-prev                             HARNESS H3: a get of soleur/<c>/<NAME> (c != prd_terraform) serves
#                                           prd_terraform's <NAME>_PREV until that name is first set (the
#                                           classification reads are poisoned, the post-write read-back is not)
log() { printf '%s\t%s\n' "$1" "$2" >> "$STUB_LOG"; }
args=("$@"); proj=""; cfg=""; i=0; dd=-1
while (( i < ${#args[@]} )); do
  case "${args[i]}" in
    --) dd=$i; break ;;
    -p) proj="${args[i+1]:-}"; i=$((i+2)) ;;
    -c) cfg="${args[i+1]:-}"; i=$((i+2)) ;;
    *) i=$((i+1)) ;;
  esac
done
F="$STUB_D/.flags"; D="$STUB_D/$proj/$cfg"
cls() { [[ -f "$1" ]] || { echo absent; return; }; case "$(cat "$1")" in SYNTH-OLD-*) echo old ;; SYNTH-NEW*|SYNTH-ACCT-*) echo new ;; *) echo other ;; esac; }
case "${1:-} ${2:-}" in
  "projects --json")
    log read "projects"
    [[ ! -e "$F/projects-fail" ]] || exit 1
    if [[ -e "$F/projects-empty" ]]; then echo '[]'; exit 0; fi
    ls -1 "$STUB_D" | jq -R -s -c 'split("\n") | map(select(length > 0)) | map({id: ., name: .})'; exit 0 ;;
  "configs -p")
    log read "configs $proj"
    [[ " $* " == *" --json "* ]] || exit 64
    [[ -n "$proj" && -d "$STUB_D/$proj" ]] || exit 1
    ls -1 "$STUB_D/$proj" | jq -R -s -c 'split("\n") | map(select(length > 0)) | map({name: ., root: false})'; exit 0 ;;
  "secrets --only-names")
    log read "list $proj/$cfg"
    [[ " $* " == *" --json "* ]] || exit 64
    [[ -n "$proj" && -n "$cfg" && -d "$D" && ! -e "$F/unreadable.$proj.$cfg" ]] || exit 1
    ls -1 "$D" | jq -R -s -c 'split("\n") | map(select(length > 0)) | map({(.): {}}) | add // {}'; exit 0 ;;
  "secrets get")
    n="$3"; log read "get $proj/$cfg/$n"
    [[ " $* " == *" --plain "* ]] || exit 64
    [[ -f "$D/$n" && ! -e "$F/get-fails.$proj.$cfg.$n" ]] || exit 1
    if [[ -e "$F/get-empty" ]]; then printf '\n'; exit 0; fi
    if [[ -e "$F/get-as-prev" && "$proj" == soleur && "$cfg" != prd_terraform && -f "$STUB_D/soleur/prd_terraform/${n}_PREV" && ! -e "$F/set-seen.$proj.$cfg.$n" ]]; then
      cat "$STUB_D/soleur/prd_terraform/${n}_PREV"; printf '\n'; exit 0
    fi
    cat "$D/$n"; printf '\n'; exit 0 ;;
  "secrets set")
    n="$3"; log mutating "set $proj/$cfg/$n prev=$(cls "$D/${n}_PREV")"; : > "$F/set-seen.$proj.$cfg.$n"
    [[ " $* " == *" --silent "* ]] || exit 64
    mkdir -p "$D"
    if [[ -e "$F/corrupt.$proj.$cfg.$n" ]]; then { cat; printf 'CORRUPTED'; } > "$D/$n"; else cat > "$D/$n"; fi
    exit 0 ;;
  "secrets delete")
    n="$3"; log mutating "delete $proj/$cfg/$n"
    [[ " $* " == *" --yes "* ]] || exit 64
    rm -f "$D/$n"; exit 0 ;;
  "run -p")
    log read "run $proj/$cfg"
    [[ "$dd" -ge 0 && -d "$D" ]] || exit 64
    envs=("DOPPLER_PROJECT=$proj" "DOPPLER_CONFIG=$cfg" "DOPPLER_ENVIRONMENT=$cfg")
    for f in "$D"/*; do [[ -f "$f" ]] && envs+=("$(basename "$f")=$(cat "$f")"); done
    exec env "${envs[@]}" "${args[@]:dd+1}" ;;
esac
log mutating "UNMODELLED $*"
exit 64
DOPPLER
  assert_fixture_dir "$b"
  cat > "$b/curl" <<'CURL'
#!/usr/bin/env bash
# Models curl on the bootstrap's call shape, `--config -` on stdin. Every URL is logged as `curl <url>`;
# a config line that is not the bearer header, the url, the JSON content type or a data line is an injected
# directive (`curl-config-extra`) and the call fails; no URL at all is `curl NOURL`, exit 2, no request.
# Verify endpoints (both): a token SYNTH-<KIND>-<KEY>-SENTINEL answers by KIND — OLD (id = the key's pinned
# prefix + 24 zeros), NEW / NEW2 / THIRD... (id = sha256 of the value), EXPIRED (status expired), all
# user-owned: /accounts/<new>/tokens/verify denies them (401 success:false) and /user/tokens/verify
# answers; ACCT is account-owned: the reverse. Anything else is denied. Flags in $STUB_D/.flags:
#   revoked-old  every OLD token is denied on both endpoints (the simulated revoke)
#   curl-429 / curl-503  every verify read answers 429 JSON success:false / 503 HTML (no verdict)
#   curl-down    every request is a transport failure (exit 7)
#   graphql-mismatch     the GraphQL answer names no zone and carries one error
# GraphQL: an ANALYTICS token of kind NEW* or ACCT gets the new zone tag and errors:null.
set -f
F="$STUB_D/.flags"
urls=(); tok=""; extra=0; data=0; ct=0
hre='^header = "Authorization: Bearer ([^"]*)"$'; ure='^url = "([^"]*)"$'
for a in "$@"; do case "$a" in https://*) urls+=("$a") ;; esac; done
while IFS= read -r line; do
  if [[ "$line" =~ $hre ]]; then tok="${BASH_REMATCH[1]}"
  elif [[ "$line" =~ $ure ]]; then [[ -z "${BASH_REMATCH[1]}" ]] || urls+=("${BASH_REMATCH[1]}")
  elif [[ "$line" == 'header = "Content-Type: application/json"' ]]; then ct=1
  elif [[ "$line" == 'data = "'*'"' ]]; then data=1
  elif [[ -n "$line" ]]; then extra=1
  fi
done < <(cat)
[[ "$extra" -eq 0 ]] || printf 'read\tcurl-config-extra\n' >> "$STUB_LOG"
[[ "${#urls[@]}" -gt 0 ]] || { printf 'read\tcurl NOURL\n' >> "$STUB_LOG"; exit 2; }
for u in "${urls[@]}"; do printf 'read\tcurl %s\n' "$u" >> "$STUB_LOG"; done
[[ "$extra" -eq 0 && "${#urls[@]}" -eq 1 ]] || exit 64
[[ ! -e "$F/curl-down" ]] || exit 7
wo=0; for a in "$@"; do [[ "$a" == -w ]] && wo=1; done
reply() { printf '%s' "$2"; [[ "$wo" -eq 0 ]] || printf '\n%s' "$1"; exit 0; }
api=https://api.cloudflare.com/client/v4; u="${urls[0]}"
deny() { reply 401 '{"success":false,"errors":[{"code":1000,"message":"Invalid API Token"}]}'; }
kre='^SYNTH-([A-Z0-9]+)-(CF_API_TOKEN_[A-Z_]+)-SENTINEL$'
kind=""; key=""
if [[ "$tok" =~ $kre ]]; then kind="${BASH_REMATCH[1]}"; key="${BASH_REMATCH[2]}"; fi
pin() { local e; for e in ${STUB_PINS:-}; do [[ "${e%%=*}" != "$1" ]] || { echo "${e#*=}"; return; }; done; echo 0000ffff; }
tid() { if [[ "$kind" == OLD ]]; then printf '%s000000000000000000000000' "$(pin "$key")"; else printf '%s' "$tok" | sha256sum | cut -c1-32; fi; }
case "$u" in
  "$api/accounts/66d4f93f7397f196544e9fe84c3557c2/tokens/verify"|"$api/user/tokens/verify")
    [[ ! -e "$F/curl-429" ]] || reply 429 '{"success":false,"errors":[{"code":971,"message":"Please wait and consider throttling your request speed"}]}'
    [[ ! -e "$F/curl-503" ]] || reply 503 '<html><body>503 Service Unavailable</body></html>'
    [[ -n "$kind" ]] || deny
    [[ "$kind" != OLD || ! -e "$F/revoked-old" ]] || deny
    acct=0; [[ "$kind" == ACCT ]] && acct=1
    if [[ "$u" == */accounts/* ]]; then [[ "$acct" -eq 1 ]] || deny; else [[ "$acct" -eq 0 ]] || deny; fi
    st=active; [[ "$kind" == EXPIRED ]] && st=expired
    reply 200 "{\"success\":true,\"result\":{\"id\":\"$(tid)\",\"status\":\"${st}\",\"expires_on\":\"2027-02-20T00:00:00Z\"}}" ;;
  "$api/graphql")
    [[ "$data" -eq 1 && "$ct" -eq 1 && " $* " == *" --max-redirs 0 "* ]] || exit 64
    if [[ "$key" == CF_API_TOKEN_ANALYTICS_READ && "$kind" =~ ^(NEW[0-9]*|ACCT)$ && ! -e "$F/graphql-mismatch" ]]; then
      reply 200 '{"data":{"viewer":{"zones":[{"zoneTag":"951ce525552201ec6c696b24251abed7"}]}},"errors":null}'
    fi
    reply 200 '{"data":{"viewer":{"zones":[]}},"errors":[{"message":"not authorized for that zone"}]}' ;;
esac
exit 64
CURL
  assert_fixture_dir "$b"
  cat > "$b/gh" <<'GH'
#!/usr/bin/env bash
# No stage may call GitHub: any call is recorded and refused.
printf 'gh %s\n' "$*" >> "$STUB_D/.gh-called"
exit 64
GH
  chmod +x "$b/doppler" "$b/curl" "$b/gh"
}

# make_repo <dir> <bootstrap-src> — a fixture repository tracking the script and the two tool stubs.
make_repo() {
  local r="$1" src="$2"; assert_fixture_dir "$r"
  mkdir -p "$r/$(dirname "$REL")" "$r/plugins/soleur/scripts" "$r/scripts"
  cp "$src" "$r/$REL"
  cat > "$r/plugins/soleur/scripts/cloudflare-readonly.sh" <<'RO'
#!/usr/bin/env bash
# Stand-in for the consumer wrapper: refuses outside soleur/prd_terraform, reads only its bound variable,
# and prints a verdict line plus a JSON projection that must never reach the bootstrap's output.
printf 'read\tconsumer %s\n' "$*" >> "$STUB_LOG"
[[ "${DOPPLER_PROJECT:-}" == soleur && "${DOPPLER_CONFIG:-}" == prd_terraform ]] || { echo 'refused source' >&2; exit 64; }
sub="${1:-}"
case "$sub" in
  pagerules-ssl) v="${CF_API_TOKEN_PAGERULES_READ:-}"; k=CF_API_TOKEN_PAGERULES_READ ;;
  change-history) v="${CF_API_TOKEN_AUDIT:-}"; k=CF_API_TOKEN_AUDIT ;;
  analytics-health) v="${CF_API_TOKEN_ANALYTICS_READ:-}"; k=CF_API_TOKEN_ANALYTICS_READ
    if [[ -e "$STUB_D/.flags/analytics-api-error" ]]; then echo "cloudflare-readonly: analytics-health unverified - api-error (graphql: quantile fields are not available on this plan)"; exit 14; fi ;;
  *) exit 64 ;;
esac
if [[ "$v" =~ ^SYNTH-(NEW[0-9]*|ACCT|EXPIRED)-${k}-SENTINEL$ ]]; then
  echo "cloudflare-readonly: ${sub} ok"; echo '{"count":2,"actor":"synth-actor@example.invalid","ip":"192.0.2.7"}'; exit 0
fi
echo "cloudflare-readonly: ${sub} unverified - token-lacks-scope"; exit 11
RO
  cat > "$r/scripts/check-cloudflare-token-drift.sh" <<'DRIFT'
#!/usr/bin/env bash
printf 'read\tdrift %s\n' "$*" >> "$STUB_LOG"
echo "drift stand-in: names only"
[[ ! -e "$STUB_D/.flags/drift-fail" ]] || exit 1
exit 0
DRIFT
  chmod +x "$r/plugins/soleur/scripts/cloudflare-readonly.sh" "$r/scripts/check-cloudflare-token-drift.sh"
  printf '.env\n.env.tmp.*\nbootstrap-runs.jsonl\n' > "$r/.gitignore"
  (
    git_fixture_env "$r" || exit 1
    cd "$r" && git init -q . && git add -A && git commit -qm fixture ) >/dev/null 2>&1 || { printf 'HARNESS: fixture repo failed\n' >&2; exit 2; }
}

# world <name> [<bootstrap-src>] — fresh state (the common configs, no manifest key yet), a fixture repo.
# HARNESS_FLAG, when set by the caller, is raised in the doppler stub for the whole world.
HARNESS_FLAG=""
world() {
  local src="${2:-$SCRIPT_SRC}"
  STEP="world"
  W="$SB/w-$1-$RANDOM"; rm -rf "$W"; mkdir -p "$W/state/.flags" "$W/xdg"
  write_stubs "$W/bin"
  make_repo "$W/repo" "$src"
  S="$W/repo/$REL"
  STUB_D="$W/state"; STUB_LOG="$W/calls.log"; : > "$STUB_LOG"
  [[ -z "$HARNESS_FLAG" ]] || : > "$STUB_D/.flags/$HARNESS_FLAG"
  sv soleur "$TFC" CF_ZONE_ID "$NZ"; sv soleur "$TFC" CF_ACCOUNT_ID "$NA"; sv soleur "$TFC" OTHER_KEY unrelated
  sv soleur dev CF_ZONE_ID "$NZ"; sv soleur dev OTHER_KEY unrelated
  sv soleur dev_personal OTHER_KEY unrelated     # its CF_API_TOKEN_AUDIT copy was deleted by hold (CTO F20)
  sv soleur dev_scheduled OTHER_KEY unrelated    # same
  sv soleur prd OTHER_KEY unrelated
  sv other ci OTHER_KEY unrelated
  sv soleur-infra-privileged prd CF_API_TOKEN_ORIGIN_CA "SYNTH-PRIV-ORIGIN-SENTINEL"
  sv soleur-infra-privileged prd CF_API_TOKEN_R2 "SYNTH-PRIV-R2-SENTINEL"
  CHILD_ENV=("PATH=$W/bin:$PATH" "SOLEUR_OP_LIB=$LIB" "ENV_FILE=$W/xdg/.env" "SOLEUR_BOOTSTRAP_LEDGER=$W/ledger.jsonl"
             "STUB_D=$STUB_D" "STUB_LOG=$STUB_LOG" "STUB_PINS=$STUB_PINS" "XDG_STATE_HOME=$W/xdg"
             "GIT_CEILING_DIRECTORIES=$SB")   # a TMPDIR inside some work tree must not leak that tree into a fixture
}
sv() { mkdir -p "$STUB_D/$1/$2"; printf '%s' "$4" > "$STUB_D/$1/$2/$3"; }   # sv <proj> <cfg> <NAME> <value>
rmv() { rm -f "$STUB_D/$1/$2/$3"; }
val() { cat "$STUB_D/$1/$2/$3" 2>/dev/null; }
has() { [[ -f "$STUB_D/$1/$2/$3" ]]; }
flag() { : > "$STUB_D/.flags/$1"; }
# seed_staged — the mint sitting is done: every <KEY>_NEXT holds a new token, <KEY> and dev's AUDIT the old one.
seed_staged() {
  local k
  for k in "${KEYS[@]}"; do sv soleur "$TFC" "$k" "$(tok OLD "$k")"; sv soleur "$TFC" "${k}_NEXT" "$(tok NEW "$k")"; done
  sv soleur dev "$KA" "$(tok OLD "$KA")"
}
# seed_swapped — swap and holder-copies are done: <KEY>_PREV old, <KEY> new, no _NEXT, dev's AUDIT new.
seed_swapped() {
  local k
  for k in "${KEYS[@]}"; do sv soleur "$TFC" "${k}_PREV" "$(tok OLD "$k")"; sv soleur "$TFC" "$k" "$(tok NEW "$k")"; done
  sv soleur dev "$KA" "$(tok NEW "$KA")"
}

OUT=""; RC=0; WHY=""
# Every child runs with the session and approval-hook variables and the git location variables removed, so a
# developer shell, a harness session or a linked worktree changes nothing about what a row observes.
UNSET_ENV=()
for _v in CLAUDE_PLUGIN_ROOT CLAUDE_CODE_ENTRYPOINT CLAUDECODE OPENCODE SOLEUR_DISABLE_OPERATOR_STAGE_APPROVAL_HOOK \
          DOPPLER_TOKEN DOPPLER_PROJECT DOPPLER_CONFIG DOPPLER_ENVIRONMENT DOPPLER_API_HOST "${GIT_LOCATION_VARS[@]}"; do
  UNSET_ENV+=(-u "$_v")
done
# observe — after every child: WHY is the reasons and markers the run printed (killed() names the one a mutant
# must produce), and a READ stage that made any mutating doppler call is forced red (rc 97, why read-stage-wrote).
observe() { # <mutating-calls-before> <read-stage 0|1>
  WHY="rc=${RC} $(grep -oE '^SOLEUR_[A-Z0-9_]+|reason=[a-z-]+' <<<"$OUT" | sort -u | tr '\n' ' ')"
  if [[ "$2" -eq 1 && "$(mut)" -gt "$1" ]]; then RC=97; WHY="read-stage-wrote ${WHY}"; OUT="read-stage-wrote: ${OUT}"; fi
  printf '%s\n' "$OUT" >> "$ALL_OUT"
}
run() {
  local before rs=0; before="$(mut)"
  [[ " $* " == *" --stage verify "* || " $* " == *" --stage inventory "* ]] && rs=1
  OUT="$(env "${UNSET_ENV[@]}" "${CHILD_ENV[@]}" timeout 120 bash "$S" "$@" </dev/null 2>&1)"; RC=$?
  observe "$before" "$rs"
}
digest() { sed -n 's/^SOLEUR_BOOTSTRAP_PLAN stage=[^ ]* operations=[0-9]* digest=\([0-9a-f]*\)$/\1/p' <<<"$OUT"; }
ops() { sed -n 's/^SOLEUR_BOOTSTRAP_PLAN stage=[^ ]* operations=\([0-9]*\) digest=.*$/\1/p' <<<"$OUT"; }
mut() { grep -c "^mutating" "$STUB_LOG" || true; }
# STEP: a row names the assertion it is about to make (`at <step>`); a row that returns non-zero leaves
# STEP at the step it stopped on. killed <rc> <step>: a mutation counts as killed only when the row went
# red AT the step its header names, never during setup.
STEP=""
at() { STEP="$1"; }
# killed <rc> <step> <why-ere> — red, AT the named step, and the last run printed the named reason (an ERE over
# WHY). Any red is not enough: a stub with no network reds most rows at their step for another reason.
killed() {
  [[ "$1" -ne 0 && "$STEP" == "$2" ]] || { echo "    row rc=$1 stopped at step '${STEP}', want '$2'"; return 1; }
  grep -qE -- "$3" <<<"$WHY" || { echo "    row red at '${STEP}' but its last run printed '${WHY}', want /$3/"; return 1; }
}
# approve <stage>: plan, the REAL hook mints a receipt for the exact apply command, then the rewritten
# command runs as the harness would run it. Leaves OUT/RC of the apply.
approve() {
  local stage="$1" d cmd in newc
  run --stage "$stage"
  d="$(digest)"
  [[ -n "$d" && "$(ops)" -gt 0 ]] || { OUT="approve(): no plan with operations for ${stage}: ${OUT}"; RC=99; WHY="approve-no-plan ${WHY}"; return; }
  cmd="bash $S --stage $stage --apply --plan-digest $d"
  in="$(jq -nc --arg c "$cmd" '{tool_name:"Bash",tool_input:{command:$c},permission_mode:"default",session_id:"s",cwd:"/",hook_event_name:"PreToolUse"}')"
  newc="$(printf '%s' "$in" | env "${UNSET_ENV[@]}" "XDG_STATE_HOME=$W/xdg" CLAUDE_CODE_ENTRYPOINT=cli bash "$HOOK" | jq -r '.hookSpecificOutput.updatedInput.command // empty')"
  [[ -n "$newc" ]] || { OUT="approve(): the hook minted nothing for: ${cmd}"; RC=98; WHY="approve-no-receipt"; return; }
  local before; before="$(mut)"
  OUT="$(env "${UNSET_ENV[@]}" "${CHILD_ENV[@]}" timeout 120 bash -c "$newc" </dev/null 2>&1)"; RC=$?
  observe "$before" 0
}
# copy_with <src> <dst> — a copy of the script with a perl edit (stdin) that must land; rc 1 when it did not land
# (the copy equals the source), rc 2 when the copy does not parse.
copy_with() {
  local src="$1" dst="$2" prog; prog="$(cat)"
  assert_fixture_dir "$dst"
  cp "$src" "$dst"; perl -0777 -pi -e "$prog" "$dst"
  ! cmp -s "$dst" "$src" || return 1
  bash -n "$dst" 2>/dev/null || return 2
}
has_line() { grep -qxF -- "$1" <<<"$OUT"; }
vok() { has_line "SOLEUR_P5_VERIFY key=$1 verdict=ok"; }
vfail_is() { has_line "SOLEUR_P5_VERIFY key=$1 verdict=fail reason=$2"; }
ready() { grep -qE "^SOLEUR_P5_REVOKE_READY key=$1 old_id=$(pin_of "$1") new_id=[0-9a-f]{8}$" <<<"$OUT"; }
noready() { ! grep -q "^SOLEUR_P5_REVOKE_READY key=$1 " <<<"$OUT"; }
logged() { grep -qE -- "$1" "$STUB_LOG"; }
set_lines() { grep -cE "^mutating	set soleur/${1}/${2} prev=" "$STUB_LOG" || true; }   # <cfg> <NAME>
# leak_scan <file> — rc 0 when no line carries 24+ consecutive lowercase hex characters, except a line that is
# EXACTLY one of the library's approval lines: the plan line, the apply-command line, the apply command itself and
# the approval-required line. Their hex is a hash of operation names or of the command text, never of a value.
# ONE awk process reads the whole file: a `grep -v | grep -q` pipeline under pipefail reports a leak as a pass on
# SIGPIPE. Only the line number and the first word of a hit are printed, never the hex.
leak_scan() {
  local h64; h64="$(printf '[0-9a-f]%.0s' $(seq 1 64))"
  LC_ALL=C awk -v hex="$(printf '[0-9a-f]%.0s' $(seq 1 24))" \
    -v e1="^SOLEUR_BOOTSTRAP_PLAN stage=[^ ]+ operations=[0-9]+ digest=${h64}\$" \
    -v e2="^SOLEUR_BOOTSTRAP_APPLY_COMMAND stage=[^ ]+ approval_digest=${h64}\$" \
    -v e3="^  bash [^ ]+ --stage [^ ]+ --apply --plan-digest ${h64}\$" \
    -v e4="^SOLEUR_BOOTSTRAP_APPROVAL_REQUIRED stage=[^ ]+ approval_digest=${h64} surface=[a-z-]+\$" '
    $0 ~ e1 || $0 ~ e2 || $0 ~ e3 || $0 ~ e4 { next }
    $0 ~ hex { bad = 1; if (shown++ < 3) printf "    leak: line %d of %s (first word %s)\n", NR, FILENAME, $1 > "/dev/stderr" }
    END { exit bad }' "$1"
}

# ==================================================================================================
# Guard 1 rows — verify's census and REVOKE_READY (world: seed_swapped, a compliant post-swap state)
# ==================================================================================================
row_g1_1_floor() { # <src>
  local k
  world g1-1 "$1"; seed_swapped; flag projects-empty
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && grep -qF 'SOLEUR_P5_CENSUS_FLOOR verdict=fail' <<<"$OUT" || return 1
  for k in "${KEYS[@]}"; do vfail_is "$k" census-floor && noready "$k" || return 1; done
}
row_g1_2_blind() { # <src> — the census reads the raw CLI output (newline kept), so it sees no old copy
  local k b="$SB/blind-$RANDOM.sh"
  at setup
  copy_with "$1" "$b" <<'PERL' || return 1
s{  HD="\$\(set -o pipefail; plain_get "\$1" "\$2" "\$3" \| soleur_approval_sha256\)"}{  HD="\$(set -o pipefail; doppler secrets get "\$3" -p "\$1" -c "\$2" --plain 2>/dev/null | soleur_approval_sha256)"}
PERL
  world g1-2 "$b"; seed_swapped
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] || return 1
  for k in "${KEYS[@]}"; do vfail_is "$k" census-blind && noready "$k" || return 1; done
}
row_g1_3_second_member() { # <src> — dev holds the new token, dev_personal (the next config) still the old one
  world g1-3 "$1"; seed_swapped; sv soleur dev_personal "$KA" "$(tok OLD "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" old-holder && noready "$KA" \
    && has_line "SOLEUR_P5_OLD_HOLDER key=${KA} holder=soleur/dev_personal/${KA}" \
    && has_line "SOLEUR_P5_HOLDER project=soleur config=dev key=${KA} value=new"
}
row_g1_4_unlisted_project() { # <src> — project other, config ci (in no manifest) holds the old value
  world g1-4 "$1"; seed_swapped; sv other ci "$KA" "$(tok OLD "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" old-holder && noready "$KA" && has_line "SOLEUR_P5_OLD_HOLDER key=${KA} holder=other/ci/${KA}" || return 1
  at no-write
  : > "$STUB_LOG"; run --stage holder-copies
  [[ "$RC" -eq 0 && "$(ops)" == 0 && "$(mut)" -eq 0 ]] && ! grep -q 'SOLEUR_BOOTSTRAP_PLAN_OP.*ci/' <<<"$OUT"
}
row_g1_5_expired() { # <src> — compliant except <KEY> verifies a new id with status=expired
  world g1-5 "$1"; seed_swapped
  sv soleur "$TFC" "$KA" "$(tok EXPIRED "$KA")"; sv soleur dev "$KA" "$(tok EXPIRED "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" key-not-active && noready "$KA"
}
row_g1_6_prev_new() { # <src> — <KEY>_PREV holds the NEW value (the #13080 order)
  world g1-6 "$1"; seed_swapped; sv soleur "$TFC" "${KA}_PREV" "$(tok NEW "$KA")"
  at source
  run --stage verify
  has_line "SOLEUR_P5_REFERENCE key=${KA} source=none" && noready "$KA" || return 1
  at verdict
  [[ "$RC" -eq 1 ]] && vfail_is "$KA" no-reference
}
row_g1_7_get_error() { # <src> — one config's get on a listed name errors
  world g1-7 "$1"; seed_swapped; sv other ci "$KA" "$(tok NEW "$KA")"; flag "get-fails.other.ci.${KA}"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line "SOLEUR_P5_UNREADABLE project=other config=ci name=${KA}" && vfail_is "$KA" census-unreadable && noready "$KA"
}
row_g1_mustpass() { # <src> — other/ci holds the NEW value and soleur/prd lacks the key: ok plus REVOKE_READY
  local k
  world g1-pass "$1"; seed_swapped; sv other ci "$KA" "$(tok NEW "$KA")"
  at verdict
  run --stage verify
  [[ "$RC" -eq 0 ]] && has_line 'SOLEUR_P5_VERIFY verdict=ok' || return 1
  for k in "${KEYS[@]}"; do vok "$k" && ready "$k" || return 1; done
  has_line "SOLEUR_P5_HOLDER project=soleur config=prd key=${KA} value=absent" \
    && has_line "SOLEUR_P5_HOLDER project=other config=ci key=${KA} value=new" \
    && has_line "SOLEUR_P5_CENSUS key=${KA} configs_read=7 old_hits=1"
}

# ==================================================================================================
# Guard 2 rows — swap (world: seed_staged)
# ==================================================================================================
REFUSE_PIN="does not verify the pinned id dd6d1427, so a swap would lose the only copy the revoke reads"
row_g2_1_key_not_pinned() { # <src> — <KEY> is not the pinned id and no _PREV exists
  world g2-1 "$1"; seed_staged; sv soleur "$TFC" "$KA" "$(tok THIRD "$KA")"
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory' && grep -qF "$REFUSE_PIN" <<<"$OUT" || return 1
  at zero-writes
  approve swap
  [[ "$(mut)" -eq 0 && "$(val soleur "$TFC" "$KA")" == "$(tok THIRD "$KA")" ]] && has soleur "$TFC" "${KA}_NEXT" && ! has soleur "$TFC" "${KA}_PREV"
}
row_g2_2_prev_by_name() { # <src> — a _PREV exists holding a non-pinned value, <KEY> not pinned
  world g2-2 "$1"; seed_staged
  sv soleur "$TFC" "${KA}_PREV" "$(tok THIRD "$KA")"; sv soleur "$TFC" "$KA" "$(tok NEW2 "$KA")"
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory' && grep -qF "$REFUSE_PIN" <<<"$OUT" || return 1
  at zero-writes
  approve swap
  [[ "$(mut)" -eq 0 && "$(val soleur "$TFC" "${KA}_PREV")" == "$(tok THIRD "$KA")" ]]
}
row_g2_3_prev_copy_mismatch() { # <src> [PREV|KEY] — which write the stub corrupts (KEY is harness H2)
  local target="${2:-PREV}" n="${KA}_PREV"
  [[ "$target" == KEY ]] && n="$KA"
  world g2-3 "$1"; seed_staged; flag "corrupt.soleur.${TFC}.${n}"
  : > "$STUB_LOG"; approve swap
  at no-key-write
  [[ "$(set_lines "$TFC" "$KA")" -eq 0 ]] || return 1
  at mismatch
  has_line "SOLEUR_P5_COPY_MISMATCH src=${TFC}/${KA} dst=${TFC}/${KA}_PREV" || return 1
  at next-kept
  [[ "$(val soleur "$TFC" "${KA}_NEXT")" == "$(tok NEW "$KA")" && "$(val soleur "$TFC" "$KA")" == "$(tok OLD "$KA")" ]] || return 1
  at stops
  [[ "$RC" -ne 0 ]] && has_line "SOLEUR_BOOTSTRAP_STAGE_FAILED stage=swap rc=1"
}
row_g2_4_second_key_fails() { # <src> — key 1 swaps, key 2's _PREV copy fails, key 3 must stay untouched
  world g2-4 "$1"; seed_staged; flag "corrupt.soleur.${TFC}.${KN}_PREV"
  : > "$STUB_LOG"; approve swap
  at mismatch
  has_line "SOLEUR_P5_COPY_MISMATCH src=${TFC}/${KN} dst=${TFC}/${KN}_PREV" || return 1
  at no-later-write
  ! logged "^mutating	set soleur/${TFC}/${KP}" && [[ "$(val soleur "$TFC" "$KP")" == "$(tok OLD "$KP")" ]] && has soleur "$TFC" "${KP}_NEXT" || return 1
  at second-untouched
  [[ "$(set_lines "$TFC" "$KN")" -eq 0 && "$(val soleur "$TFC" "$KN")" == "$(tok OLD "$KN")" ]] && has soleur "$TFC" "${KN}_NEXT" || return 1
  at first-swapped
  [[ "$(val soleur "$TFC" "$KA")" == "$(tok NEW "$KA")" && "$(val soleur "$TFC" "${KA}_PREV")" == "$(tok OLD "$KA")" ]] && ! has soleur "$TFC" "${KA}_NEXT" || return 1
  at stops
  [[ "$RC" -ne 0 ]]
}
row_g2_5_order_in_window() { # <src> — every <KEY> write happens while <KEY>_PREV already holds the old value
  local k
  world g2-5 "$1"; seed_staged
  : > "$STUB_LOG"; approve swap
  at prev-old
  for k in "${KEYS[@]}"; do
    [[ "$(set_lines "$TFC" "$k")" -eq 1 ]] && logged "^mutating	set soleur/${TFC}/${k} prev=old$" || return 1
  done
  at applied
  [[ "$RC" -eq 0 ]] || return 1
  for k in "${KEYS[@]}"; do
    [[ "$(val soleur "$TFC" "$k")" == "$(tok NEW "$k")" && "$(val soleur "$TFC" "${k}_PREV")" == "$(tok OLD "$k")" ]] && ! has soleur "$TFC" "${k}_NEXT" \
      && has_line "SOLEUR_P5_SWAPPED key=${k} staging=deleted verified=digest" || return 1
  done
}
row_g2_6_empty_manifest() { # <src> — the manifest block parses to zero keys
  local b="$SB/nomanifest-$RANDOM.sh"
  at setup
  copy_with "$1" "$b" <<'PERL' || return 1
s{^# P5-MANIFEST [^\n]*\n}{}mg
PERL
  world g2-6 "$b"; seed_staged
  at refuse
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line 'SOLEUR_P5_MANIFEST_EMPTY' && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory' || return 1
  at zero-writes
  approve swap
  [[ "$(mut)" -eq 0 ]]
}
row_g2_mustpass() { # <src> — key 1 swapped in an earlier sitting, key 2 staged, key 3 not staged
  world g2-pass "$1"; seed_staged
  rmv soleur "$TFC" "${KA}_NEXT"; sv soleur "$TFC" "${KA}_PREV" "$(tok OLD "$KA")"; sv soleur "$TFC" "$KA" "$(tok NEW "$KA")"
  rmv soleur "$TFC" "${KP}_NEXT"
  cp "$STUB_D/soleur/$TFC/${KA}_PREV" "$W/audit-prev.before"
  at writes-key-2-only
  : > "$STUB_LOG"; approve swap
  [[ "$RC" -eq 0 && "$(val soleur "$TFC" "$KN")" == "$(tok NEW "$KN")" && "$(val soleur "$TFC" "${KN}_PREV")" == "$(tok OLD "$KN")" ]] && ! has soleur "$TFC" "${KN}_NEXT" || return 1
  [[ "$(grep -c '^mutating	set ' "$STUB_LOG")" -eq 2 ]] && ! logged "set soleur/${TFC}/${KA}" && ! logged "set soleur/${TFC}/${KP}" || return 1
  cmp -s "$W/audit-prev.before" "$STUB_D/soleur/$TFC/${KA}_PREV" && [[ "$(val soleur "$TFC" "$KP")" == "$(tok OLD "$KP")" ]]
}

# ==================================================================================================
# Guard 3 rows — holder-copies (world: seed_swapped with AUDIT's holders still old)
# ==================================================================================================
# two_holders <src> <dst> — the manifest with AUDIT holders soleur/dev_personal then soleur/dev (a rotation
# edits only the manifest block, so this is a legitimate input world).
two_holders() {
  copy_with "$1" "$2" <<'PERL'
s{(# P5-MANIFEST CF_API_TOKEN_AUDIT +\| dd6d1427 +\| soleur/prd_terraform) soleur/dev\n}{$1 soleur/dev_personal soleur/dev\n}
PERL
}
row_g3_1_last_holder_bad() { # <src> <third|absent>
  local b="$SB/twoh-$RANDOM.sh" want=other
  at setup
  two_holders "$1" "$b" || return 1
  world "g3-1-$2" "$b"; seed_swapped; sv soleur dev_personal "$KA" "$(tok OLD "$KA")"
  if [[ "$2" == third ]]; then sv soleur dev "$KA" "$(tok THIRD "$KA")"; else rmv soleur dev "$KA"; want=absent; fi
  at refuse
  : > "$STUB_LOG"; run --stage holder-copies
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line "SOLEUR_P5_HOLDER_REFUSED key=${KA} holder=soleur/dev value=${want}" \
    && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=holder-copies need=inventory' || return 1
  at zero-writes
  approve holder-copies
  [[ "$(mut)" -eq 0 && "$(val soleur dev_personal "$KA")" == "$(tok OLD "$KA")" ]]
}
row_g3_2_second_already_new() { # <src> — first holder old, second already new: writes only the first
  local b="$SB/twoh-$RANDOM.sh"
  at setup
  two_holders "$1" "$b" || return 1
  world g3-2 "$b"; seed_swapped; sv soleur dev_personal "$KA" "$(tok OLD "$KA")"
  : > "$STUB_LOG"; approve holder-copies
  at only-first
  [[ "$(set_lines dev "$KA")" -eq 0 && "$(set_lines dev_personal "$KA")" -eq 1 ]] || return 1
  at applied
  [[ "$RC" -eq 0 && "$(val soleur dev_personal "$KA")" == "$(tok NEW "$KA")" && "$(val soleur dev "$KA")" == "$(tok NEW "$KA")" ]] \
    && has_line "SOLEUR_P5_COPIED src=${TFC}/${KA} dst=dev_personal/${KA} verified=digest"
}
row_g3_3_before_swap() { # <src>
  world g3-3 "$1"; seed_staged
  at need-swap
  : > "$STUB_LOG"; run --stage holder-copies
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=holder-copies need=swap' && grep -qF '_NEXT is still staged' <<<"$OUT" || return 1
  at zero-writes
  [[ "$(mut)" -eq 0 ]]
}

# ==================================================================================================
# Scenario rows
# ==================================================================================================
row_s1_happy_path() { # <src>
  local k st
  world s1 "$1"; seed_staged
  at inventory-pre
  run --stage inventory
  [[ "$RC" -eq 0 ]] || return 1
  for k in "${KEYS[@]}"; do has_line "SOLEUR_P5_STAGED key=${k} next=present prev=absent" && has_line "SOLEUR_P5_REFERENCE key=${k} source=KEY" || return 1; done
  at swap
  approve swap
  [[ "$RC" -eq 0 && "$(grep -c '^SOLEUR_P5_SWAPPED ' <<<"$OUT")" -eq 3 ]] || return 1
  at holder-copies
  approve holder-copies
  [[ "$RC" -eq 0 && "$(val soleur dev "$KA")" == "$(tok NEW "$KA")" ]] || return 1
  at verify
  run --stage verify
  [[ "$RC" -eq 0 ]] && has_line 'SOLEUR_P5_VERIFY verdict=ok' && has_line "SOLEUR_P5_GRAPHQL key=${KN} zone_tag=match errors=0" || return 1
  for k in "${KEYS[@]}"; do vok "$k" && ready "$k" && has_line "SOLEUR_P5_DRIFT key=${k} rc=0" || return 1; done
  ! grep -qE '"count"|synth-actor|192\.0\.2\.7' <<<"$OUT" || return 1
  at revoke
  flag revoked-old
  for k in "${KEYS[@]}"; do rmv soleur "$TFC" "${k}_PREV"; done    # the revoke recipe's step-4 key delete (a hold)
  run --stage inventory
  [[ "$RC" -eq 0 ]] || return 1
  for k in "${KEYS[@]}"; do
    has_line "SOLEUR_P5_REFERENCE key=${k} source=none" && has_line "SOLEUR_P5_STAGED key=${k} next=absent prev=absent" \
      && has_line "SOLEUR_P5_HOLDER project=soleur config=${TFC} key=${k}_PREV value=absent" || return 1
  done
  at satisfied
  for st in swap holder-copies; do
    : > "$STUB_LOG"; run --stage "$st"
    [[ "$RC" -eq 0 && "$(ops)" == 0 && "$(mut)" -eq 0 ]] || return 1
  done
  at no-github
  [[ ! -e "$STUB_D/.gh-called" ]]
}
row_s2_account_owned() { # <src> — /user/tokens/verify refuses, the account endpoint answers active
  world s2 "$1"; seed_swapped; sv soleur "$TFC" "$KA" "$(tok ACCT "$KA")"; sv soleur dev "$KA" "$(tok ACCT "$KA")"
  at verdict
  : > "$STUB_LOG"; run --stage verify
  [[ "$RC" -eq 0 ]] && vok "$KA" && ready "$KA" && grep -qE "^SOLEUR_P5_KEY key=${KA} id=[0-9a-f]{8} status=active owner=account$" <<<"$OUT"
}
row_s3_unreachable() { # <src> — 429 on verify reads in verify, 503 in the swap plan: no verdict either way
  world s3a "$1"; seed_swapped; flag curl-429
  at verify-unreachable
  run --stage verify
  [[ "$RC" -eq 1 ]] && has_line "SOLEUR_P5_TOKEN_UNREACHABLE name=soleur/${TFC}/${KA} http=429" && vfail_is "$KA" unreachable \
    && ! grep -q '^SOLEUR_P5_REVOKE_READY ' <<<"$OUT" || return 1
  world s3b "$1"; seed_staged; flag curl-503
  at swap-unreachable
  : > "$STUB_LOG"; run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" && "$(mut)" -eq 0 ]] && has_line "SOLEUR_P5_TOKEN_UNREACHABLE name=soleur/${TFC}/${KA}_NEXT http=503" \
    && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory'
}
row_s4_no_receipt() { # <src> — an apply without a receipt exits 75 and writes nothing
  local d
  world s4a "$1"; seed_staged
  at swap-75
  run --stage swap; d="$(digest)"; [[ -n "$d" && "$(ops)" -gt 0 ]] || return 1
  : > "$STUB_LOG"; run --stage swap --apply --plan-digest "$d"
  [[ "$RC" -eq 75 && "$(mut)" -eq 0 ]] && grep -q '^SOLEUR_BOOTSTRAP_APPROVAL_REQUIRED stage=swap ' <<<"$OUT" || return 1
  world s4b "$1"; seed_swapped; sv soleur dev "$KA" "$(tok OLD "$KA")"
  at holder-copies-75
  run --stage holder-copies; d="$(digest)"; [[ -n "$d" && "$(ops)" == 1 ]] || return 1
  : > "$STUB_LOG"; run --stage holder-copies --apply --plan-digest "$d"
  [[ "$RC" -eq 75 && "$(mut)" -eq 0 ]] && grep -q '^SOLEUR_BOOTSTRAP_APPROVAL_REQUIRED stage=holder-copies ' <<<"$OUT"
}
row_s5_malformed_next() { # <src> <quote|newline> — the LAST key's staged value is malformed
  world "s5-$2" "$1"; seed_staged
  if [[ "$2" == quote ]]; then sv soleur "$TFC" "${KP}_NEXT" 'SYNTH-BAD"QUOTE-SENTINEL'
  else printf '%s\n%s' 'SYNTH-BAD-LINE1' 'url = "https://injected.invalid/"' > "$STUB_D/soleur/$TFC/${KP}_NEXT"; fi
  : > "$STUB_LOG"
  at refuse
  run --stage swap
  [[ "$RC" -eq 1 && -z "$(digest)" ]] && has_line "SOLEUR_P5_TOKEN_MALFORMED name=soleur/${TFC}/${KP}_NEXT" \
    && has_line 'SOLEUR_BOOTSTRAP_PRECONDITION_FAILED stage=swap need=inventory' || return 1
  at no-curl
  ! logged 'curl' || return 1
  at zero-writes
  [[ "$(mut)" -eq 0 ]]
}
row_s6_analytics_api_error() { # <src> — the zone-tag query passes and analytics-health says api-error: still ok
  world s6 "$1"; seed_swapped; flag analytics-api-error
  at verdict
  run --stage verify
  [[ "$RC" -eq 0 ]] && vok "$KN" && ready "$KN" && has_line "SOLEUR_P5_GRAPHQL key=${KN} zone_tag=match errors=0" \
    && grep -qE "^SOLEUR_P5_CONSUMER key=${KN} sub=analytics-health gating=no rc=14 line=cloudflare-readonly: analytics-health unverified - api-error \(graphql: " <<<"$OUT"
}
row_s7_graphql_mismatch() { # <src>
  world s7 "$1"; seed_swapped; flag graphql-mismatch
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] && vfail_is "$KN" consumer-read && noready "$KN" && has_line "SOLEUR_P5_GRAPHQL key=${KN} zone_tag=mismatch errors=1" && vok "$KA"
}
row_s8_old_target_ids() { # <src> — prd_terraform still names the old zone: refused as a target
  local k
  world s8 "$1"; seed_swapped; sv soleur "$TFC" CF_ZONE_ID "$OZ"
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] || return 1
  for k in "${KEYS[@]}"; do vfail_is "$k" target-ids-not-new && noready "$k" || return 1; done
  ! logged 'consumer '
}
row_s9_drift_fails() { # <src>
  local k
  world s9 "$1"; seed_swapped; flag drift-fail
  at verdict
  run --stage verify
  [[ "$RC" -eq 1 ]] || return 1
  for k in "${KEYS[@]}"; do vfail_is "$k" drift && has_line "SOLEUR_P5_DRIFT key=${k} rc=1" && noready "$k" || return 1; done
}

# ==================================================================================================
# The rows on the real script (full mode)
# ==================================================================================================
if [[ "$MODE" == full ]]; then
  echo "== static contract =="
  r=1; [[ "$(sed -n 2p "$SCRIPT_SRC")" == '# SOLEUR-GENERATED-OPERATOR-SCRIPT v2' ]] && r=0
  check "line 2 is the v2 generated-script header" "$r"
  OUT="$(bash "$SCRIPT_SRC" --list 2>&1)"; RC=$?
  r=1; [[ "$RC" -eq 0 && "$OUT" == "$(printf '%s\n' 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=inventory class=read' 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=swap class=write' 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=holder-copies class=write' 'SOLEUR_BOOTSTRAP_STAGE_DECL stage=verify class=read')" ]] && r=0
  check "--list prints the four stages in table order with their class (AC2)" "$r"
  [[ "$(grep -c '^# P5-MANIFEST ' "$SCRIPT_SRC")" -eq 3 ]] \
    && grep -qE '^# P5-MANIFEST CF_API_TOKEN_AUDIT +\| dd6d1427 +\| soleur/prd_terraform soleur/dev$' "$SCRIPT_SRC" \
    && grep -qE '^# P5-MANIFEST CF_API_TOKEN_ANALYTICS_READ +\| 5993721f +\| soleur/prd_terraform$' "$SCRIPT_SRC" \
    && grep -qE '^# P5-MANIFEST CF_API_TOKEN_PAGERULES_READ +\| 86aa993e +\| soleur/prd_terraform$' "$SCRIPT_SRC"
  check "the manifest block holds the three keys, their pinned ids and holders (plan Phase 3)" $?
  ! grep -nE 'soleur-infra-privileged' <(grep -v '^#' "$SCRIPT_SRC" | grep -vE '^[[:space:]]*#')
  check "no executable line names soleur-infra-privileged (no stage writes there)" $?
  world static
  run --stage no-such-stage
  [[ "$RC" -eq 64 ]] && has_line 'SOLEUR_BOOTSTRAP_UNKNOWN_STAGE stage=no-such-stage'
  check "an undeclared stage exits 64 UNKNOWN_STAGE" $?
  run
  [[ "$RC" -eq 64 ]] && has_line 'SOLEUR_BOOTSTRAP_STAGE_REQUIRED'
  check "no --stage exits 64 STAGE_REQUIRED (no run-all mode)" $?
  OUT="$(env "${UNSET_ENV[@]}" "${CHILD_ENV[@]}" bash -x "$S" --stage inventory </dev/null 2>&1)"; RC=$?
  [[ "$RC" -eq 78 ]] && grep -qF '[FATAL] refusing to run under xtrace' <<<"$OUT"
  check "a run under xtrace is refused with exit 78" $?

  echo "== Guard 1: verify's census and REVOKE_READY =="
  row_g1_1_floor "$SCRIPT_SRC"; check "G1-1 doppler projects answers []: fail reason=census-floor, no REVOKE_READY" $?
  row_g1_2_blind "$SCRIPT_SRC"; check "G1-2 a census that cannot see the old value: fail reason=census-blind" $?
  row_g1_3_second_member "$SCRIPT_SRC"; check "G1-3 dev new, dev_personal old: fail naming soleur/dev_personal" $?
  row_g1_4_unlisted_project "$SCRIPT_SRC"; check "G1-4 other/ci (in no manifest) holds the old value: fail naming other/ci; holder-copies plans nothing there" $?
  row_g1_5_expired "$SCRIPT_SRC"; check "G1-5 <KEY> verifies a new id with status=expired: fail reason=key-not-active" $?
  row_g1_6_prev_new "$SCRIPT_SRC"; check "G1-6 <KEY>_PREV holds the new value: source=none, no REVOKE_READY" $?
  row_g1_7_get_error "$SCRIPT_SRC"; check "G1-7 a failed get of a listed name: UNREADABLE, fail reason=census-unreadable" $?
  row_g1_mustpass "$SCRIPT_SRC"; check "G1 must-PASS: other/ci new and soleur/prd absent: ok plus REVOKE_READY for all three keys" $?

  echo "== Guard 2: swap =="
  row_g2_1_key_not_pinned "$SCRIPT_SRC"; check "G2-1 <KEY> not the pinned id, no _PREV: refuse with the named sentence, zero writes" $?
  row_g2_2_prev_by_name "$SCRIPT_SRC"; check "G2-2 a _PREV holding a non-pinned value: refuse (value, not name), zero writes" $?
  row_g2_3_prev_copy_mismatch "$SCRIPT_SRC"; check "G2-3 the _PREV copy does not read back equal: COPY_MISMATCH, no <KEY> write, _NEXT kept" $?
  row_g2_4_second_key_fails "$SCRIPT_SRC"; check "G2-4 key 2's _PREV copy fails: key 2 and key 3 untouched, their _NEXT kept" $?
  row_g2_5_order_in_window "$SCRIPT_SRC"; check "G2-5 every set <KEY> is logged prev=old (the order observed inside the write window)" $?
  row_g2_6_empty_manifest "$SCRIPT_SRC"; check "G2-6 a manifest that parses to zero keys: MANIFEST_EMPTY refusal, zero writes" $?
  row_g2_mustpass "$SCRIPT_SRC"; check "G2 must-PASS: key 1 swapped earlier, key 2 staged: writes key 2 only, key 1's _PREV unchanged" $?

  echo "== Guard 3: holder-copies =="
  row_g3_1_last_holder_bad "$SCRIPT_SRC" third; check "G3-1 the last holder (dev) holds a third value: refuse naming it, zero writes" $?
  row_g3_1_last_holder_bad "$SCRIPT_SRC" absent; check "G3-1 the last holder (dev) lacks the key: refuse naming it, zero writes" $?
  row_g3_2_second_already_new "$SCRIPT_SRC"; check "G3-2 first holder old, second already new: writes only the first" $?
  row_g3_3_before_swap "$SCRIPT_SRC"; check "G3-3 run before swap: PRECONDITION_FAILED need=swap" $?

  echo "== Test Scenarios =="
  row_s1_happy_path "$SCRIPT_SRC"; check "S1 happy path: swap, holder-copies, verify ok with three REVOKE_READY, revoke, inventory source=none, every write stage satisfied, no GitHub call" $?
  row_s2_account_owned "$SCRIPT_SRC"; check "S2 an account-owned new token (user endpoint refuses) reads as new and active" $?
  row_s3_unreachable "$SCRIPT_SRC"; check "S3 429 / 503 on a verify read is TOKEN_UNREACHABLE and the stage refuses, never a verdict" $?
  row_s4_no_receipt "$SCRIPT_SRC"; check "S4 an apply without a receipt exits 75 and writes nothing (swap and holder-copies)" $?
  row_s5_malformed_next "$SCRIPT_SRC" quote; check "S5 a staged value with a quote is refused before any curl call" $?
  row_s5_malformed_next "$SCRIPT_SRC" newline; check "S5 a staged value with an embedded newline is refused before any curl call" $?
  row_s6_analytics_api_error "$SCRIPT_SRC"; check "S6 ANALYTICS: zone-tag match plus an analytics-health api-error still reads ok" $?
  row_s7_graphql_mismatch "$SCRIPT_SRC"; check "S7 ANALYTICS: a GraphQL answer without the new zone tag fails reason=consumer-read" $?
  row_s8_old_target_ids "$SCRIPT_SRC"; check "S8 prd_terraform still on the old zone id: target-ids-not-new, no consumer read" $?
  row_s9_drift_fails "$SCRIPT_SRC"; check "S9 a failing drift check fails reason=drift" $?

  echo "== P-leak: no synthesized value, digest or full id in any output =="
  ! grep -qE 'SYNTH-|synth-actor|192\.0\.2\.7|injected\.invalid' "$ALL_OUT"
  check "no SYNTH-* value, consumer body field or injected URL appears in any stdout/stderr" $?
  leak_scan "$ALL_OUT"
  check "no digest or full id (24+ hex) appears on any line but the exact SOLEUR_BOOTSTRAP_PLAN digest line" $?
fi

# ==================================================================================================
# The instrument: the leak scanner and the mutant scorer must each be able to say no
# ==================================================================================================
echo "== instrument controls =="
LEAK_PLANT="$SB/leak-plant.log"; LEAK_CLEAN="$SB/leak-clean.log"
{ printf 'SOLEUR_P5_READBACK digest-check=%s\n' "$(printf 'plant' | sha256sum | cut -c1-64)"
  for _i in $(seq 1 3000); do printf 'SOLEUR_P5_HOLDER project=soleur config=dev key=CF_API_TOKEN_AUDIT value=new %s\n' "$_i"; done; } > "$LEAK_PLANT"
{ printf 'SOLEUR_BOOTSTRAP_PLAN stage=swap operations=3 digest=%s\n' "$(printf 'plan' | sha256sum | cut -c1-64)"; tail -n +2 "$LEAK_PLANT"; } > "$LEAK_CLEAN"
r=1; [[ "$(wc -c < "$LEAK_PLANT")" -gt 102400 ]] && ! leak_scan "$LEAK_PLANT" && r=0
check "control: a 64-hex line planted FIRST in a >100 KB log turns the leak scan red" "$r"
leak_scan "$LEAK_CLEAN"
check "control: the same log whose only 64-hex line is an exact SOLEUR_BOOTSTRAP_PLAN line passes the leak scan" $?

# score <row-fn> <src> <step> <why-ere> [<row-args>...] — rc 0 when the row went red as named (killed()).
score() {
  local fn="$1" src="$2" step="$3" why="$4" r; shift 4
  "$fn" "$src" "$@"; r=$?
  killed "$r" "$step" "$why"
}
# ctl_row <src> <step> <why> <rc> — a printf-and-exit stand-in for a row, for the scorer controls.
ctl_row() { at "$2"; WHY="$3"; printf '    control row: step=%s why=%s rc=%s\n' "$2" "$3" "$4"; return "$4"; }
! score ctl_row - named 'reason=wanted' named 'rc=0 reason=wanted ' 0 >/dev/null
check "control: the scorer rejects a row that stayed green (rc 0)" $?
! score ctl_row - named 'reason=wanted' elsewhere 'rc=1 reason=wanted ' 1 >/dev/null
check "control: the scorer rejects a row that went red at another step" $?
! score ctl_row - named 'reason=wanted' named 'rc=1 reason=other ' 1 >/dev/null
check "control: the scorer rejects a row that went red at the named step for another reason" $?
score ctl_row - named 'reason=wanted' named 'rc=1 reason=wanted ' 1 >/dev/null
check "control: the scorer accepts a row that went red at the named step with the named reason" $?

if [[ "$MODE" == mutants ]]; then
  # The pristine pass: on the UNMUTATED script these rows must be green, or every "killed" below is noise.
  row_g1_mustpass "$SCRIPT_SRC" && row_g2_5_order_in_window "$SCRIPT_SRC" \
    || { printf 'HARNESS: a pristine row is red on the unmutated script (step %s; %s), so no mutant verdict means anything\n' "$STEP" "$WHY" >&2; exit 2; }
fi

# ==================================================================================================
# Mutations and harness rows (full mode tail, and --mutants)
# ==================================================================================================
echo "== mutations =="
mutate() { # <label> <dst> — perl program on stdin, applied to the real script by copy_with(); proves it landed
  local label="$1" dst="$2" r=0
  copy_with "$SCRIPT_SRC" "$dst" || r=$?
  case "$r" in
    0) pass "mutation ${label} landed (differs from the source, bash -n clean)" ;;
    1) fail "mutation ${label} did not land"; return 1 ;;
    *) fail "mutation ${label} does not parse"; return 1 ;;
  esac
}
# mkill <label> <row-fn> <src> <step> <why-ere> [<row-args>...] — the row must go red AT <step> for <why>.
mkill() { local label="$1"; shift; score "$@"; check "${label} turns ${1#row_} RED at step ${3} (/${4}/)" $?; }

if mutate G1M1 "$SB/g1m1.sh" <<'PERL'; then
s{  \[\[ "\$CT_FLOOR_OK" -eq 1 \]\] \|\| \{ vfail "\$k" census-floor; return 0; \}\n}{}
PERL
  mkill "G1M1 (census floor deleted)" row_g1_1_floor "$SB/g1m1.sh" verdict 'reason=census-blind'
  # The scorer's no-network control: the same mutant under a curl that never connects reds the same row at the
  # same step, but for another reason, and must NOT count as killed.
  HARNESS_FLAG=curl-down; ! score row_g1_1_floor "$SB/g1m1.sh" verdict 'reason=census-blind' >/dev/null; r=$?; HARNESS_FLAG=""
  check "control: G1M1 under a curl that never connects is NOT scored as killed (red for another reason)" "$r"
fi
if mutate G1M2 "$SB/g1m2.sh" <<'PERL'; then
s{  \[\[ "\$C_OLD" -eq 1 && "\$C_PREV_OLD" -eq 1 \]\] \|\| \{ vfail "\$k" census-blind; return 0; \}\n}{}
PERL
  mkill "G1M2 (old_hits check deleted)" row_g1_2_blind "$SB/g1m2.sh" verdict 'SOLEUR_P5_REVOKE_READY '
fi
if mutate G1M3 "$SB/g1m3.sh" <<'PERL'; then
s{(      printf 'SOLEUR_P5_HOLDER project=%s config=%s key=%s value=%s\\n' "\$p" "\$c" "\$n" "\$v"\n)}{$1      [[ "\$v" == old ]] || break 2\n}
PERL
